  1→<script lang="ts">
  2→	// AC: @web-dashboard ac-12, ac-13, ac-14, ac-15
  3→	import type { ItemDetail, TaskSummary } from '@kynetic-ai/shared';
  4→	import { base } from '$app/paths';
  5→	import { Badge } from '$lib/components/ui/badge';
  6→	import {
  7→		Sheet,
  8→		SheetContent,
  9→		SheetDescription,
 10→		SheetHeader,
 11→		SheetTitle
 12→	} from '$lib/components/ui/sheet';
 13→	import {
 14→		Accordion,
 15→		AccordionContent,
 16→		AccordionItem,
 17→		AccordionTrigger
 18→	} from '$lib/components/ui/accordion';
 19→	import { Skeleton } from '$lib/components/ui/skeleton';
 20→	import ReferenceLink from '$lib/components/ReferenceLink.svelte';
 21→	import { fetchItem, fetchItemTasks } from '$lib/api';
 22→	import { CheckCircle, XCircle, HelpCircle } from 'lucide-svelte';
 23→
 24→	interface Props {
 25→		ref: string | null;
 26→		open: boolean;
 27→	}
 28→
 29→	let { ref, open = $bindable(false) }: Props = $props();
 30→
 31→	let item = $state<ItemDetail | null>(null);
 32→	let linkedTasks = $state<TaskSummary[]>([]);
 33→	let loading = $state(false);
 34→	let error = $state<string | null>(null);
 35→
 36→	async function loadItem(itemRef: string) {
 37→		loading = true;
 38→		error = null;
 39→		try {
 40→			// Fetch item details
 41→			item = await fetchItem(itemRef);
 42→
 43→			// Fetch linked tasks
 44→			// AC: @web-dashboard ac-13
 45→			const tasksResponse = await fetchItemTasks(itemRef);
 46→			linkedTasks = tasksResponse.items;
 47→		} catch (err) {
 48→			error = err instanceof Error ? err.message : 'Failed to load item';
 49→			item = null;
 50→			linkedTasks = [];
 51→		} finally {
 52→			loading = false;
 53→		}
 54→	}
