 61→
 62→	function getStatusColor(status: string): string {
 63→		const colors: Record<string, string> = {
 64→			pending: 'bg-status-pending text-status-pending-fg',
 65→			in_progress: 'bg-status-in-progress text-status-in-progress-fg',
 66→			pending_review: 'bg-status-pending-review text-status-pending-review-fg',
