 68→			blocked: 'bg-status-blocked text-status-blocked-fg',
 69→			completed: 'bg-status-completed text-status-completed-fg',
 70→			cancelled: 'bg-status-cancelled text-status-cancelled-fg'
 71→		};
 72→		return colors[status] || 'bg-status-cancelled text-status-cancelled-fg';
 73→	}
