 75→	function formatStatus(status: string): string {
 76→		const labels: Record<string, string> = {
 77→			pending: 'Pending',
 78→			in_progress: 'In Progress',
 79→			pending_review: 'Pending Review',
 80→			needs_work: 'Needs Work',
 81→			blocked: 'Blocked',
 82→			completed: 'Completed',
 83→			cancelled: 'Cancelled'
 84→		};
 85→		return labels[status] || status;
 86→	}
