  1→<!--
  2→  AC: @ui-reference-display ac-1 — Shared ReferenceLink component for consistent display
  3→  of cross-references (task, spec, plan, session). Normalizes @ prefix, shows resolved
  4→  title with slug/ULID as secondary, and links to the appropriate detail view.
  5→  Falls back to raw ref display if resolution fails.
  6→-->
  7→<script lang="ts">
  8→	import { base } from '$app/paths';
  9→	import { goto } from '$app/navigation';
 10→	import type { RefType } from '$lib/utils/reference';
 11→	import { normalizeRef, shortRef, refHref } from '$lib/utils/reference';
 12→
 13→	interface Props {
 14→		/** The raw reference string (may include @ prefix). */
 15→		ref: string;
 16→		/** The entity type this reference points to. */
 17→		type: RefType;
 18→		/** Resolved title for the entity, if available. */
 19→		title?: string | null;
 20→		/** Whether to render as a clickable link (default: true). */
 21→		linked?: boolean;
 22→		/**
 23→		 * Use an interactive <span> instead of <a> for the link.
 24→		 * Navigates via goto() on click. Use when nested inside <a> or <button>
 25→		 * to avoid invalid HTML (nested interactive elements).
 26→		 * Implies stopPropagation and preventDefault.
 27→		 */
 28→		inline?: boolean;
 29→		/** Stop click propagation (useful when nested inside clickable containers). */
 30→		stopPropagation?: boolean;
 31→		/** Additional CSS classes. */
 32→		class?: string;
 33→	}
 34→
 35→	let {
 36→		ref: rawRef,
 37→		type,
 38→		title = null,
 39→		linked = true,
 40→		inline = false,
 41→		stopPropagation = false,
 42→		class: className = ''
 43→	}: Props = $props();
 44→
 45→	let normalized = $derived(normalizeRef(rawRef));
 46→	let short = $derived(shortRef(rawRef));
 47→	let href = $derived(refHref(type, rawRef, base));
 48→
 49→	function handleClick(e: MouseEvent) {
 50→		if (stopPropagation) {
 51→			e.stopPropagation();
 52→		}
 53→	}
 54→
 55→	function handleInlineClick(e: Event) {
 56→		e.stopPropagation();
 57→		e.preventDefault();
 58→		goto(href);
 59→	}
 60→</script>
 61→
 62→{#snippet refContent()}
 63→	{#if title}
 64→		<span class="text-sm">{title}</span>
 65→		<span class="text-[10px] font-mono text-muted-foreground">@{short}</span>
 66→	{:else}
 67→		<span class="text-sm font-mono">@{normalized}</span>
 68→	{/if}
 69→{/snippet}
 70→
 71→{#if linked && inline}
 72→	<!-- Interactive span: navigates via goto(), safe inside <a>/<button> -->
 73→	<span
 74→		class="inline-flex items-baseline gap-1 text-primary hover:underline cursor-pointer {className}"
 75→		onclick={handleInlineClick}
 76→		onkeydown={(e) => e.key === 'Enter' && handleInlineClick(e)}
 77→		title={rawRef}
 78→		role="link"
 79→		tabindex="0"
 80→		data-testid="reference-link"
 81→		data-ref-type={type}
 82→		data-href={href}
 83→	>
 84→		{@render refContent()}
 85→	</span>
 86→{:else if linked}
 87→	<a
 88→		{href}
 89→		class="inline-flex items-baseline gap-1 text-primary hover:underline {className}"
 90→		onclick={handleClick}
 91→		title={rawRef}
 92→		data-testid="reference-link"
 93→		data-ref-type={type}
 94→	>
 95→		{@render refContent()}
 96→	</a>
 97→{:else}
 98→	<span
 99→		class="inline-flex items-baseline gap-1 {className}"
100→		title={rawRef}
101→		data-testid="reference-link"
102→		data-ref-type={type}
103→	>
104→		{#if title}
